Two files follow. I read the approved extension as an import of `aap:caps/http-client@0.1.0`, since that is the interface that offers outbound HTTP.

- **Output unchanged:** the enrichment call uses `fetch`, not `get`, so a transport failure comes back as a value and can't trap the node. The result is discarded.
- **Query text:** the Tick's only field is `reason`, so that is what goes into `q=`, percent-encoded.
- **`date` length:** the seconds used for `date` are clamped to year 9999, so it is always `YYYY-MM-DD` (10 characters). `started` is the unclamped seconds and is never negative because it is a `u64`.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;
    import aap:caps/http-client@0.1.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 15) as usize] as char);
            }
        }
    }
    out
}

fn format_date(seconds: u64) -> String {
    // Clamp to 9999-12-31T23:59:59Z so the year always has four digits.
    let secs = seconds.min(253_402_300_799) as i64;
    let days = secs / 86_400;
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch: result intentionally ignored so output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&tick.reason)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let now = crate::wasi::clocks::wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
